  shocks: [
    { id: "hormuz", n: "Gulf PP exports blocked at Hormuz", u: "Mt", min: 0, max: 6, st: .1, def: 2, why: "Saudi Arabia exported about 4.5 Mt in 2024 (Comtrade, desk tonnage), mostly from Jubail inside the Gulf; Iran's exports are already blocked. Modelled as supply lost to buyers. Desk sizing.", eff: v => -v },
    { id: "usg", n: "US Gulf Coast outage", u: "Mt", min: 0, max: 2, st: .1, def: .5, why: "A hurricane or freeze that shuts Texas and Louisiana plants for weeks. US exports were about 1.85 Mt in 2024 (desk). Desk sizing.", eff: v => -v },
    { id: "cncap", n: "Chinese start-ups", u: "Mt", min: 0, max: 6, st: .1, def: 3, why: "China adds about 5.7 Mt of capacity in 2026 (PCMA). Modelled as extra supply buyers must absorb. Bearish.", eff: v => +v },
    { id: "dem", n: "Restocking demand", u: "Mt", min: 0, max: 3, st: .1, def: 1, why: "Converters rebuilding stocks after months of buying to need. Desk sizing.", eff: v => -v },
    { id: "propane", n: "Propane price change", u: "%", min: -30, max: 40, st: 1, def: 10, why: "PDH uses about 1.2 t of propane per tonne of PP (assumption). Passed through to price at today's $720/t Aramco CP.", add: v => v / 100 * 1.2 * B.cp.usd },
    { id: "oil", n: "Brent crude", u: "$/bbl", min: 50, max: 150, st: 1, def: 96, base: D.brentNow.v, why: `From $${D.brentNow.v} (${D.brentNow.date.slice(5)}, US EIA). Pass-through of $4/t of PP per $1/bbl via naphtha: an assumption. Do not combine with a large propane shock; they overlap.`, add: v => (v - D.brentNow.v) * 4 },
    { id: "ad", n: "Import duty or anti-dumping", u: "$/t", min: 0, max: 150, st: 5, def: 40, why: "Extra landed cost where duties apply, such as Indonesia's proposed 5.52-36.62% on homopolymer. Desk assumption; added to delivered price.", add: v => v },
    { id: "red", n: "Red Sea freight premium", u: "$/t", min: 0, max: 60, st: 1, def: 15, why: "Extra cost of Cape diversions on Gulf and Asia to Europe lanes; added to delivered price. Desk assumption.", add: v => v }],
  presets: [["Today", {}], ["Hormuz shut", { hormuz: 5, oil: 130 }], ["China build-out", { cncap: 5.7 }], ["Feedstock squeeze", { propane: 30, oil: 115 }], ["Hurricane season", { usg: 1.5 }], ["Perfect storm", { hormuz: 3, usg: 1, dem: 2, propane: 25, oil: 120, ad: 60, red: 40 }]],
