  rules: (daysTo, recent) => { const sp = pdh(), bw = curve[5].t / curve[1].t - 1, last = ser("pp").at(-1)[1], a5 = avg5(), hz = (D.chokepoints.find(c => c.id === "hormuz") || {}).status; return [
    { st: sp < 250 ? "fire" : sp < 350 ? "arm" : "calm", t: "PDH spread at the floor", tr: "PP ex-VAT less 1.2 × propane below $250/t (armed at $350); desk thresholds", now: `$${f0(sp)}/t`, a: "PDH plants cut runs when the spread is thin; prices tend to stop falling. Extend cover." },
    { st: bw < -.05 ? "fire" : bw < 0 ? "arm" : "calm", t: "Curve pays you to wait", tr: "May 27 more than 5% under Jan", now: `Jan $${f0(curve[1].t)} vs May $${f0(curve[5].t)} (${pct(bw)})`, a: "Buy only what you need now; leave Q2-Q3 open or on index." },
    { st: last > a5 * 1.2 ? "fire" : last > a5 * 1.1 ? "arm" : "calm", t: "Price stretched above its five-year average", tr: "Monthly PP more than 20% over its 5y mean (armed at 10%)", now: `$${f0(last)} vs $${f0(a5)} (${pct(last / a5 - 1)})`, a: "Rallies this far above average have not tended to last when capacity is growing. Do not lock long fixed prices here." },
    { st: hz === "bad" ? "fire" : hz === "warn" ? "arm" : "calm", t: "Hormuz disrupted", tr: "Strait status on the Logistics screen is 'bad' (armed at 'watch')", now: hz === "bad" ? "Attacks and blockade" : "Open", a: "Name a non-Gulf back-up for every grade and keep two to four extra weeks of stock for Gulf-sourced items." },
    { st: D.brentNow.v > 100 ? "fire" : D.brentNow.v > 85 ? "arm" : "calm", t: "Crude lifts naphtha costs", tr: "Brent above $100 (armed at $85)", now: `Brent $${H.f2(D.brentNow.v)} (${D.brentNow.date.slice(5)})`, a: "Naphtha-based PP follows crude within weeks. Test supplier increases against the crude move, not the headline." },
    { st: [8, 9, 10].includes(NOWM) ? "fire" : [6, 7, 11].includes(NOWM) ? "arm" : "calm", t: "US hurricane season", tr: "Aug to Oct (armed Jun, Jul and Nov)", now: NOWM === 11 ? `Season ends 30 Nov · ${daysTo("2026-11-30")} days` : "In window", a: "If you buy US resin, keep a few weeks' extra stock through peak season and know your force-majeure terms." },
    { st: daysTo("2027-02-06") <= 30 ? "fire" : daysTo("2027-02-06") <= 90 ? "arm" : "calm", t: "Chinese New Year slowdown", tr: "Within 90 days of 6 Feb 2027", now: `${daysTo("2027-02-06")} days to go`, a: "Chinese plants and ports slow for two weeks. Land Asian cargoes for February before mid-January." },
    { st: recent > 3 ? "fire" : recent > -3 ? "arm" : "calm", t: "News turns bullish", tr: "Net news pressure over 14 days above +3", now: `Net ${recent > 0 ? "+" : ""}${recent} (${recent < 0 ? "bearish" : "bullish"})`, a: "When the flow of news turns, pull planned purchases forward." }]; },
  ladder: () => [["Q1 27", curve[3].t, "Mar 27"], ["Q2 27", curve[5].t, "May 27"], ["Q3 27", curve[8].t, "Aug 27"], ["Q4 27", curve[10].t, "Oct 27"]],
